import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO

# Set plot style
sns.set_theme(style="whitegrid")

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

def get_base64_img():
    buf = BytesIO()
    plt.savefig(buf, format='png', bbox_inches='tight')
    plt.close()
    return base64.b64encode(buf.getvalue()).decode('utf-8')

html_content = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
    <style>
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: #333;
            max-width: 1000px;
            margin: 0 auto;
            padding: 20px;
            background-color: #f9f9f9;
        }}
        h1, h2, h3 {{
            color: #2c3e50;
        }}
        h1 {{
            border-bottom: 2px solid #3498db;
            padding-bottom: 10px;
        }}
        .section {{
            background: #fff;
            padding: 20px;
            margin-bottom: 20px;
            border-radius: 8px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.1);
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 20px;
        }}
        th, td {{
            padding: 12px;
            border-bottom: 1px solid #ddd;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
        }}
        .img-container {{
            text-align: center;
            margin: 20px 0;
        }}
        img {{
            max-width: 100%;
            height: auto;
            border: 1px solid #eee;
            border-radius: 4px;
        }}
        .kpi-container {{
            display: flex;
            justify-content: space-between;
            margin-bottom: 20px;
        }}
        .kpi-card {{
            background: #ecf0f1;
            padding: 15px;
            border-radius: 5px;
            width: 30%;
            text-align: center;
        }}
        .kpi-card h3 {{
            margin: 0 0 10px 0;
            font-size: 1.1em;
            color: #2c3e50;
        }}
        .kpi-card p {{
            margin: 0;
            font-size: 1.5em;
            font-weight: bold;
            color: #2980b9;
        }}
    </style>
</head>
<body>
    <h1>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</h1>
    <p><strong>Executive Summary:</strong> A comprehensive analysis of how book pricing strategies relate to customer satisfaction across Fiction and Non-Fiction genres over a decade of Amazon bestseller data.</p>
"""

# Section 1: Market Overview
total_books = len(df)
unique_books = df['Name'].nunique()
genre_counts = df['Genre'].value_counts()
avg_price = df['Price'].mean()
avg_rating = df['User Rating'].mean()
avg_reviews = df['Reviews'].mean()

html_content += f"""
    <div class="section">
        <h2>1. Bestseller Market Overview (2009–2019)</h2>
        <div class="kpi-container">
            <div class="kpi-card">
                <h3>Total Bestsellers</h3>
                <p>{total_books}</p>
                <small>({unique_books} unique titles)</small>
            </div>
            <div class="kpi-card">
                <h3>Average Price</h3>
                <p>${avg_price:.2f}</p>
            </div>
            <div class="kpi-card">
                <h3>Average Rating</h3>
                <p>{avg_rating:.2f} / 5</p>
            </div>
        </div>
        <p>Over the 11-year period, the top 50 bestsellers each year (550 total records) generated an average of {avg_reviews:,.0f} reviews per book. The market is relatively balanced, with {genre_counts.get('Non Fiction', 0)} Non-Fiction and {genre_counts.get('Fiction', 0)} Fiction books making the list.</p>
    </div>
"""

# Section 2: Price-Rating Correlation
correlation = df['Price'].corr(df['User Rating'])
plt.figure(figsize=(10, 6))
sns.scatterplot(data=df, x='Price', y='User Rating', hue='Genre', alpha=0.7)
plt.title('Price vs. User Rating by Genre')
plt.xlabel('Price ($)')
plt.ylabel('User Rating (0-5)')
img_corr = get_base64_img()

html_content += f"""
    <div class="section">
        <h2>2. Price vs. User Rating: Correlation Analysis</h2>
        <p>The Pearson correlation coefficient between price and user rating is <strong>{correlation:.4f}</strong>. This indicates a negligible negative correlation. Pricing does not strongly dictate customer satisfaction among bestselling books. Customers evaluate books based on content quality rather than price paid, at least within the typical price range of bestsellers.</p>
        <div class="img-container">
            <img src="data:image/png;base64,{img_corr}" alt="Price vs Rating Scatter Plot">
        </div>
    </div>
"""

# Section 3: Genre Comparison
genre_stats = df.groupby('Genre').agg(
    Avg_Price=('Price', 'mean'),
    Avg_Rating=('User Rating', 'mean'),
    Avg_Reviews=('Reviews', 'mean'),
    Count=('Name', 'count')
).reset_index()

plt.figure(figsize=(15, 5))
plt.subplot(1, 3, 1)
sns.barplot(data=genre_stats, x='Genre', y='Avg_Price', hue='Genre', palette='pastel', legend=False)
plt.title('Average Price ($)')
plt.subplot(1, 3, 2)
sns.barplot(data=genre_stats, x='Genre', y='Avg_Rating', hue='Genre', palette='pastel', legend=False)
plt.title('Average Rating (0-5)')
plt.ylim(4.0, 5.0)
plt.subplot(1, 3, 3)
sns.barplot(data=genre_stats, x='Genre', y='Avg_Reviews', hue='Genre', palette='pastel', legend=False)
plt.title('Average Reviews')
plt.tight_layout()
img_genre = get_base64_img()

html_content += f"""
    <div class="section">
        <h2>3. Fiction vs. Non-Fiction: Pricing and Rating Strategies</h2>
        <p>Non-Fiction bestsellers are generally priced higher than Fiction, while Fiction bestsellers accumulate significantly more reviews and have a slightly higher average user rating.</p>
        <table>
            <tr>
                <th>Genre</th>
                <th>Count</th>
                <th>Avg. Price</th>
                <th>Avg. Rating</th>
                <th>Avg. Reviews</th>
            </tr>
"""
for _, row in genre_stats.iterrows():
    html_content += f"""
            <tr>
                <td>{row['Genre']}</td>
                <td>{row['Count']}</td>
                <td>${row['Avg_Price']:.2f}</td>
                <td>{row['Avg_Rating']:.2f}</td>
                <td>{row['Avg_Reviews']:,.0f}</td>
            </tr>
"""
html_content += f"""
        </table>
        <div class="img-container">
            <img src="data:image/png;base64,{img_genre}" alt="Genre Comparison Charts">
        </div>
    </div>
"""

# Section 4: Temporal Trends
plt.figure(figsize=(15, 12))
plt.subplot(3, 1, 1)
sns.lineplot(data=df, x='Year', y='Price', hue='Genre', marker='o')
plt.title('Average Book Price Over Time (2009-2019)')
plt.ylabel('Price ($)')
plt.xticks(range(2009, 2020))

plt.subplot(3, 1, 2)
sns.lineplot(data=df, x='Year', y='User Rating', hue='Genre', marker='o')
plt.title('Average User Rating Over Time (2009-2019)')
plt.ylabel('Rating')
plt.xticks(range(2009, 2020))

plt.subplot(3, 1, 3)
sns.lineplot(data=df, x='Year', y='Reviews', hue='Genre', marker='o')
plt.title('Average Review Count Over Time (2009-2019)')
plt.ylabel('Reviews')
plt.xticks(range(2009, 2020))

plt.tight_layout()
img_trend = get_base64_img()

html_content += f"""
    <div class="section">
        <h2>4. Year-over-Year Trends in Pricing and Ratings</h2>
        <p>Over the decade, we observe several key shifts:</p>
        <ul>
            <li><strong>Prices are dropping:</strong> There is a clear downward trend in average book prices since 2009, likely driven by the rise of e-books, Kindle Unlimited, and promotional pricing strategies.</li>
            <li><strong>Ratings are rising:</strong> User ratings have seen a slight upward trajectory. This may reflect improved curation by publishers or rating inflation on the platform over time.</li>
            <li><strong>Explosion in review volume:</strong> The average number of reviews has skyrocketed, especially in the later years, indicating massive growth in digital engagement and Amazon's expanding customer base.</li>
        </ul>
        <div class="img-container">
            <img src="data:image/png;base64,{img_trend}" alt="Yearly Trend Charts">
        </div>
    </div>
"""

# Section 5: Top Authors
top_authors = df['Author'].value_counts().head(10).reset_index()
top_authors.columns = ['Author', 'Appearances']
top_authors_stats = top_authors.merge(df, on='Author').groupby('Author').agg(
    Appearances=('Appearances', 'first'),
    Avg_Price=('Price', 'mean'),
    Avg_Rating=('User Rating', 'mean'),
    Genres=('Genre', lambda x: ', '.join(set(x)))
).sort_values(by='Appearances', ascending=False).reset_index()

html_content += f"""
    <div class="section">
        <h2>5. Dominant Authors on the Bestseller List</h2>
        <p>The following authors have achieved the most frequent appearances on the annual bestseller list from 2009 to 2019. Their consistent ability to maintain high ratings demonstrates sustained customer satisfaction and brand loyalty.</p>
        <table>
            <tr>
                <th>Author</th>
                <th>Bestseller Appearances</th>
                <th>Avg. Price</th>
                <th>Avg. Rating</th>
                <th>Genres</th>
            </tr>
"""
for _, row in top_authors_stats.iterrows():
    html_content += f"""
            <tr>
                <td>{row['Author']}</td>
                <td>{row['Appearances']}</td>
                <td>${row['Avg_Price']:.2f}</td>
                <td>{row['Avg_Rating']:.2f}</td>
                <td>{row['Genres']}</td>
            </tr>
"""
html_content += f"""
        </table>
    </div>
"""

# Section 6: Recommendations
html_content += f"""
    <div class="section">
        <h2>6. Strategic Recommendations</h2>
        <ul>
            <li><strong>Price Is Not a Proxy for Quality:</strong> Given the negligible correlation between price and user rating ({correlation:.4f}), publishers should not artificially suppress prices assuming it will buy better reviews, nor fear that premium pricing will necessarily harm ratings. Content quality and audience fit remain paramount.</li>
            <li><strong>Leverage the Genre Split:</strong> Non-Fiction commands a consistently higher average price point. Publishers can afford to price substantial Non-Fiction titles at a premium. Conversely, Fiction relies heavily on volume and massive review accumulation, favoring competitive pricing to drive volume.</li>
            <li><strong>Adapt to the E-book Reality:</strong> The decade-long downward trend in average prices signals increased market pressure. Pricing strategies must account for a highly competitive, digital-first marketplace where lower-cost entry points are increasingly common.</li>
            <li><strong>Invest in Review Generation:</strong> The dramatic increase in review volumes since 2009 shows that social proof is more important than ever. Bestsellers now accumulate tens of thousands of reviews; early and aggressive review-generation campaigns are essential for new releases to break through the noise.</li>
        </ul>
    </div>
</body>
</html>
"""

with open('/app/output/final_report.html', 'w') as f:
    f.write(html_content)
print("Report generated successfully.")

